import { drizzle } from 'drizzle-orm/d1';
import { auditEvents } from '../db/audit-schema';
import { redactDbMessage } from './errors';

export type SecurityAuditResult = 'success' | 'denied' | 'error';

export interface SecurityAuditEvent {
  actionName: string;
  resource: string;
  operation: string;
  reason: string;
  targetScope: 'organization' | 'all';
  result: SecurityAuditResult;
  targetOrgId?: string;
  targetRecordId?: string;
  rowCount?: number;
  errorCode?: string;
  errorMessage?: string;
  metadata?: Record<string, unknown>;
  resultData?: unknown;
}

export interface HardDeleteAuditEvent {
  resource: string;            // table name (e.g. 'invoices')
  operation: 'delete' | 'batch_delete';
  targetRecordId: string;      // primary key of the deleted row
  targetOrgId?: string;
  before: unknown;             // pre-delete row, serialized as JSON
  rowCount?: number;
  metadata?: Record<string, unknown>;
}

function inferRowCount(value: unknown): number | undefined {
  if (Array.isArray(value)) return value.length;
  if (!value || typeof value !== 'object') return undefined;

  const rowCount = (value as any).rowCount;
  if (typeof rowCount === 'number') return rowCount;

  const affected = (value as any).affectedRows;
  if (typeof affected === 'number') return affected;

  return 1;
}

function normalizeRequestId(c: any): string {
  const requestId = c?.req?.header?.('x-request-id')
    || c?.req?.header?.('cf-ray')
    || c?.req?.header?.('x-correlation-id');
  if (requestId && typeof requestId === 'string') return requestId;
  return crypto.randomUUID();
}

function getAuditDb(c: any) {
  const binding = c?.env?.AUDIT_DB;
  if (!binding) {
    throw new Error(
      'Missing AUDIT_DB binding. Audit logging is mandatory for ' +
      'unsafe cross-tenant actions and hard deletes. Add compiler.migrations/audit ' +
      'DB config and bind the audit database.'
    );
  }
  return drizzle(binding);
}

export async function logSecurityAudit(c: any, event: SecurityAuditEvent): Promise<void> {
  const db = getAuditDb(c);
  const ctx = c?.get?.('ctx') || {};
  const rowCount = typeof event.rowCount === 'number' ? event.rowCount : inferRowCount(event.resultData);

  await db.insert(auditEvents).values({
    id: crypto.randomUUID(),
    requestId: normalizeRequestId(c),
    eventKind: 'unsafe_action',
    actorUserId: ctx.userId || null,
    actorUserRole: ctx.userRole || null,
    actorOrgId: ctx.activeOrgId || null,
    actionName: event.actionName,
    resource: event.resource,
    operation: event.operation,
    targetScope: event.targetScope,
    targetOrgId: event.targetOrgId || null,
    targetRecordId: event.targetRecordId || null,
    unsafeReason: event.reason,
    beforeImage: null,
    result: event.result,
    rowCount: typeof rowCount === 'number' ? rowCount : null,
    errorCode: event.errorCode || null,
    // Never a bound value in the audit row: callers pass redactError(e).message,
    // and the writer strips again so no caller can forget.
    errorMessage: event.errorMessage ? redactDbMessage(event.errorMessage) : null,
    metadata: event.metadata ? JSON.stringify(event.metadata) : null,
    createdAt: new Date(),
  });
}

/**
 * Records a hard DELETE in audit_events. Fail-closed — if the insert
 * throws, the caller's request must fail before the row is actually
 * deleted. Generated DELETE handlers call this BEFORE issuing the
 * underlying `db.delete(...)` so an audit-DB outage never erases a row
 * silently.
 */
export async function logHardDelete(c: any, event: HardDeleteAuditEvent): Promise<void> {
  const db = getAuditDb(c);
  const ctx = c?.get?.('ctx') || {};

  await db.insert(auditEvents).values({
    id: crypto.randomUUID(),
    requestId: normalizeRequestId(c),
    eventKind: 'hard_delete',
    actorUserId: ctx.userId || null,
    actorUserRole: ctx.userRole || null,
    actorOrgId: ctx.activeOrgId || null,
    actionName: event.operation,
    resource: event.resource,
    operation: event.operation,
    targetScope: event.targetOrgId ? 'organization' : 'all',
    targetOrgId: event.targetOrgId || null,
    targetRecordId: event.targetRecordId,
    unsafeReason: null,
    beforeImage: JSON.stringify(event.before),
    result: 'success',
    rowCount: typeof event.rowCount === 'number' ? event.rowCount : 1,
    errorCode: null,
    errorMessage: null,
    metadata: event.metadata ? JSON.stringify(event.metadata) : null,
    createdAt: new Date(),
  });
}

